    let artifacts = cask_artifacts(&cask)?;
    assert_eq!(
        artifacts.postflight_steps,
        vec![FlightStep::Run {
            command: FlightPath {
                base: FlightPathBase::AppDir,
                path: "OrbStack.app/Contents/MacOS/bin/orbctl".to_string(),
            },
            args: vec!["_internal".to_string(), "brew-postflight".to_string()],
            env: BTreeMap::new(),
            sudo: false,
            guards: Vec::new(),
        }]
    );
    Ok(())
}

