  end

  def arch(mapping = nil, **values)
    mapping = values if mapping.nil? && values.any?
    return @arch || Hardware::CPU.arch.to_s if mapping.nil?
    @arch = Hardware::CPU.arm? ? mapping[:arm] || mapping["arm"] : mapping[:intel] || mapping["intel"]
